import 'package:adaptive_screen_utils/adaptive_screen_utils.dart';

class MyWidget extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    final desktop = expanded(context);
    final tablet = medium(context);
    return Scaffold(
      appBar: AppBar(
        title: Text('Adaptive Screen Utils'),
      ),
      body: Builder(
        builder: (context) {
         if (desktop) {
            return Center(child: Text('Desktop'));
          } else if (tablet) {
            return Center(child: Text('Tablet'));
          }
          return Center(child: Text('Mobile'));
        },
      ),
    );
  }
}
